const g = $('Guard').first().json;
const j = $json;
const esc = s => String(s).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
const ist = new Date().toLocaleString('sv-SE', { timeZone: 'Asia/Kolkata' }) + ' IST';
const verdict = j.valid ? (j.attempt === 1 ? 'VALID' : 'REPAIRED') : 'INVALID';
const sev = j.valid ? j.level : 'n/a';
const t = (j.rule.match(/^title:\s*(.+)$/m) || [, 'no title'])[1].trim();
let summary = j.valid ? t : 'Validation failed: ' + j.errors.join('; ');
if (g.injection) summary += ' [prompt-injection attempt detected and ignored]';
const header = `🟣 NGP-050 | exec #${$execution.id} | ${ist} | ${verdict} / ${sev} | ${summary}`;
const body = j.valid ? j.rule : j.rule + '\n\n# ERRORS\n# ' + j.errors.join('\n# ');
const text = esc(header) + '\n\n<pre><code class="language-yaml">' + esc(body) + '</code></pre>';
return [{ json: { chat_id: g.chat_id, text } }];

const cq = $json.callback_query;
const esc = s => String(s).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
const ist = new Date().toLocaleString('sv-SE', { timeZone: 'Asia/Kolkata' }) + ' IST';
const who = cq.from.username ? '@' + cq.from.username : cq.from.first_name;
const orig = cq.message.text || '';
const i = orig.indexOf('\n\n');
const header = i > -1 ? orig.slice(0, i) : orig;
const rule = i > -1 ? orig.slice(i + 2) : '';
const act = cq.data === 'ack' ? '✅ Acknowledged' : '🚫 Ignored';
const text = esc(header) + '\n\n<pre><code class="language-yaml">' + esc(rule) + '</code></pre>\n\n' + act + ' by ' + esc(who) + ' at ' + ist;
return [{ json: { query_id: cq.id, chat_id: cq.message.chat.id, message_id: cq.message.message_id, act, text } }];
